#include <stdio.h>
#include <stdlib.h>
#include <math.h>

static inline float M(float a, float b) { volatile float r = a * b; return r; }
static inline float A(float a, float b) { volatile float r = a + b; return r; }
static inline float S(float a, float b) { volatile float r = a - b; return r; }
static inline float D(float a, float b) { volatile float r = a / b; return r; }
static inline float FM(float a, float b, float c) { return fmaf(a, b, c); }

typedef struct { float x, y, z; } V;
typedef struct { V o, d; } Ray;
typedef struct { float t, x, y, z, nx, ny, nz; int hit; } Hit;

static Hit sph(Ray *r, float cx, float cy, float cz, float rad)
{
	Hit h;
	float ocy = S(r->o.y, cy), ocx = S(r->o.x, cx), ocz = S(r->o.z, cz);
	float c = M(ocy, ocy);
	float a = M(r->d.y, r->d.y);
	float b = M(ocy, r->d.y);
	float b2, a4, disc, twa, t, px, py, pz, nx0, ny0, nz0, l;
	double sq, nb, dtwa;
	h.t = 0.0f; h.x = 0.0f; h.y = 0.0f; h.z = 0.0f;
	h.nx = 0.0f; h.ny = 0.0f; h.nz = 0.0f; h.hit = 0;
	c = FM(ocx, ocx, c);
	a = FM(r->d.x, r->d.x, a);
	b = FM(ocx, r->d.x, b);
	c = FM(ocz, ocz, c);
	a = FM(r->d.z, r->d.z, a);
	b = FM(ocz, r->d.z, b);
	c = FM(-rad, rad, c);
	b2 = A(b, b);
	a4 = M(a, 4.0f);
	disc = FM(-b2, b2, M(a4, c));
	if (disc < 0.0f)
		return h;
	sq = sqrt((double)disc);
	twa = A(a, a);
	dtwa = (double)twa;
	nb = -(double)b2;
	t = (float)((nb - sq) / dtwa);
	if (t < 1e-3f) {
		t = (float)((nb + sq) / dtwa);
		if (t < 1e-3f)
			return h;
	}
	px = FM(t, r->d.x, r->o.x);
	py = FM(t, r->d.y, r->o.y);
	pz = FM(t, r->d.z, r->o.z);
	ny0 = S(py, cy);
	nx0 = S(px, cx);
	nz0 = S(pz, cz);
	l = M(ny0, ny0);
	l = FM(nx0, nx0, l);
	l = FM(nz0, nz0, l);
	l = sqrtf(l);
	h.t = t; h.x = px; h.y = py; h.z = pz;
	h.nx = D(nx0, l); h.ny = D(ny0, l); h.nz = D(nz0, l);
	h.hit = 1;
	return h;
}

static void write_image(float **im, const char *fn, int w, int h)
{
	FILE *fp = fopen(fn, "w");
	int x, y, k, c[3], ci;
	float K = 255.99f, *p;
	double d;
	if (!fp) {
		fprintf(stderr, "Error: Could not open file %s for writing\n", fn);
		return;
	}
	fprintf(fp, "P3\n%d %d\n255\n", w, h);
	for (y = 0; y < h; y++)
		for (x = 0; x < w; x++) {
			p = im[y] + 3 * x;
			for (k = 0; k < 3; k++) {
				d = (double)p[k];
				d = fmax(d, 0.0);
				d = fmin(d, 1.0);
				ci = (int)M((float)d, K);
				c[k] = ci;
			}
			fprintf(fp, "%d %d %d\n", c[0], c[1], c[2]);
		}
	fclose(fp);
	fprintf(stderr, "Wrote image to %s\n", fn);
}

int main(void)
{
	float **img, *row, l0, l1, l2, s, Y, pr, zr, tz, u, dy, dx, dz, sl, tp;
	float cr, cg, cb, px, py, pz, ox, oy, oz, ls, v, dot, f6, f4, fac, cc;
	float diff;
	int y, x, wh, pok;
	double dd, sm;
	Ray r, sr;
	Hit h, sh;

	fprintf(stderr, "Creating high-resolution image: %dx%d\n", 800, 600);
	fwrite("This will be downsampled with ffmpeg after rendering\n", 1, 53, stderr);
	l0 = 1.0f; l1 = 1.0f; l2 = -1.0f;
	s = M(l1, l1); s = FM(l0, l0, s); s = FM(l2, l2, s); s = sqrtf(s);
	l0 = D(l0, s); l1 = D(l1, s); l2 = D(l2, s);
	img = malloc(600 * sizeof(float *));
	for (y = 0; y < 600; y++)
		img[y] = malloc(800 * 3 * sizeof(float));
	fwrite("Rendering high-resolution image...\n", 1, 35, stderr);
	for (y = 0; y < 600; y++) {
		Y = (float)y;
		pr = D(M(Y, 100.0f), 600.0f);
		fprintf(stderr, "\rProgress: %.1f%%", (double)pr);
		zr = S(1.0f, D(Y, 599.0f));
		tz = A(zr, zr);
		row = img[y];
		for (x = 0; x < 800; x++) {
			u = D((float)x, 799.0f);
			dy = S(tz, 1.0f);
			dx = S(M(u, 2.6666667f), 1.3333334f);
			dz = -1.0f;
			sl = M(dy, dy); sl = FM(dx, dx, sl); sl = FM(dz, dz, sl);
			sl = sqrtf(sl);
			r.o.x = 0.0f; r.o.y = 0.0f; r.o.z = 0.0f;
			r.d.x = D(dx, sl); r.d.y = D(dy, sl); r.d.z = D(dz, sl);
			h = sph(&r, 0.0f, -0.5f, -5.0f, 1.0f);
			pok = 0; tp = 0.0f;
			if (!(fabsf(r.d.y) < 1e-4f)) {
				tp = D(-1.5f, r.d.y);
				if (!(tp < 1e-3f))
					pok = 1;
			}
			if (pok && h.hit)
				wh = (tp > h.t) ? 1 : 0;
			else if (pok)
				wh = 0;
			else if (h.hit)
				wh = 1;
			else
				wh = 2;
			if (wh == 2) {
				u = M(A(r.d.y, 1.0f), 0.5f);
				s = S(1.0f, u);
				cr = FM(u, 0.5f, s);
				cg = FM(u, 0.7f, s);
				cb = A(u, s);
			} else {
				if (wh == 1) {
					px = h.x; py = h.y; pz = h.z;
					ox = FM(h.nx, 1e-3f, px);
					oy = A(M(h.ny, 1e-3f), py);
					oz = FM(h.nz, 1e-3f, pz);
				} else {
					px = M(r.d.x, tp);
					py = M(r.d.y, tp);
					pz = M(r.d.z, tp);
					ox = px; oy = A(1e-3f, py); oz = pz;
				}
				ls = M(l1, l1); ls = FM(l0, l0, ls); ls = FM(l2, l2, ls);
				ls = sqrtf(ls);
				sr.o.x = ox; sr.o.y = oy; sr.o.z = oz;
				sr.d.x = D(l0, ls); sr.d.y = D(l1, ls); sr.d.z = D(l2, ls);
				sh = sph(&sr, 0.0f, -0.5f, -5.0f, 1.0f);
				if (sh.hit) {
					v = 0.2f;
				} else {
					dot = (wh == 1) ? FM(h.nz, l2, FM(h.nx, l0, M(h.ny, l1))) : l1;
					dd = (double)dot;
					dd = fmax(dd, 0.0);
					diff = (float)dd;
					v = FM(diff, 0.8f, 0.2f);
				}
				if (wh == 1) {
					cr = v; cg = M(v, 0.2f); cb = cg;
				} else {
					f6 = floorf(px);
					f4 = floorf(pz);
					sm = (double)f6 + (double)f4;
					wh = (int)sm;
					fac = (wh & 1) ? 0.4f : 0.9f;
					cc = M(v, fac);
					cr = cc; cg = cc; cb = cc;
				}
			}
			row[3 * x] = cr;
			row[3 * x + 1] = cg;
			row[3 * x + 2] = cb;
		}
	}
	fwrite("\nRendering complete\n", 1, 20, stderr);
	write_image(img, "image.ppm", 800, 600);
	for (y = 0; y < 600; y++)
		free(img[y]);
	free(img);
	fwrite("Done.\n", 1, 6, stderr);
	return 0;
}

